package com.fertiplus.order;import jakarta.persistence.*;import java.time.Instant;@Entity @Table(name="customer_orders") public class OrderEntity {@Id @GeneratedValue(strategy=GenerationType.UUID) public String id;@Column(nullable=false) public String customerId;@Column(nullable=false) public Long productId;@Column(nullable=false) public int quantity;@Column(nullable=false) public double total;@Column(nullable=false) public String status;@Column(nullable=false,unique=true) public String idempotencyKey;@Column(nullable=false) public Instant createdAt=Instant.now();protected OrderEntity(){}public OrderEntity(String customerId,Long productId,int quantity,double total,String status,String key){this.customerId=customerId;this.productId=productId;this.quantity=quantity;this.total=total;this.status=status;this.idempotencyKey=key;}}
